using System.IO;
using UnrealBuildTool;

public class HoMoLapPhysics : ModuleRules
{
	public HoMoLapPhysics(ReadOnlyTargetRules Target) : base(Target)
	{
		PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
		PublicDependencyModuleNames.Add("Core");
		// the team's ADTM, generated by tools\adtm\adtm_codegen.m; without it FS Lap builds with its own model only
		bool bAdtm = File.Exists(Path.Combine(ModuleDirectory, "Private", "ADTM", "adtm_indices.h"));
		PrivateDefinitions.Add("HOMOLAP_WITH_ADTM=" + (bAdtm ? "1" : "0"));
	}
}
